WITH exploded AS (SELECT id, customer_id, key, v FROM carts LATERAL VIEW EXPLODE(attributes) li AS key, v) SELECT customer_id, key, COUNT(*) FILTER (WHERE key = 'gift') AS gift_rows, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(CASE WHEN key = 'utm_source' THEN 1 END) AS utm_source_count, COUNT(DISTINCT customer_id) AS distinct_customer_ids_2, GROUPING_ID() AS gid FROM exploded GROUP BY GROUPING SETS ((customer_id, key), (customer_id), ()) ORDER BY distinct_customer_ids_2 DESC
